/*
 * `app calc`: 64-bit signed integer expression evaluator.
 *
 * Each input line is one expression:
 *
 *     expr    := term    (('+' | '-') term)*
 *     term    := unary   (('*' | '/' | '%') unary)*
 *     unary   := '-' unary | primary
 *     primary := NUMBER | '(' expr ')'
 *
 * The evaluator is an iterative operator-precedence (shunting-yard) parser
 * with explicit, heap-allocated stacks, so arbitrarily deep nesting such as
 * "((((...))))" or "-----...1" cannot exhaust the C call stack. Both stacks
 * are bounded by the line length and reused across lines.
 */
#include "calc.h"

#include <inttypes.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ------------------------------------------------------------------------ */
/* Checked 64-bit arithmetic                                                */
/* ------------------------------------------------------------------------ */

enum calc_status {
    CALC_OK,
    CALC_ERROR,     /* syntax error, division by zero or overflow */
    CALC_NOMEM,
};

static bool checked_add(int64_t a, int64_t b, int64_t *r)
{
    if ((b > 0 && a > INT64_MAX - b) || (b < 0 && a < INT64_MIN - b))
        return false;
    *r = a + b;
    return true;
}

static bool checked_sub(int64_t a, int64_t b, int64_t *r)
{
    if ((b < 0 && a > INT64_MAX + b) || (b > 0 && a < INT64_MIN + b))
        return false;
    *r = a - b;
    return true;
}

static bool checked_mul(int64_t a, int64_t b, int64_t *r)
{
    if (a > 0) {
        if (b > 0 ? a > INT64_MAX / b : b < INT64_MIN / a)
            return false;
    } else if (a < 0) {
        if (b > 0 ? a < INT64_MIN / b : (b != 0 && a < INT64_MAX / b))
            return false;
    }
    *r = a * b;
    return true;
}

static bool checked_div(int64_t a, int64_t b, int64_t *r)
{
    if (b == 0 || (a == INT64_MIN && b == -1))
        return false;
    *r = a / b;
    return true;
}

static bool checked_mod(int64_t a, int64_t b, int64_t *r)
{
    if (b == 0)
        return false;
    /* INT64_MIN % -1 is mathematically 0 but undefined behaviour in C. */
    *r = (b == -1) ? 0 : a % b;
    return true;
}

static bool checked_neg(int64_t a, int64_t *r)
{
    if (a == INT64_MIN)
        return false;
    *r = -a;
    return true;
}

/* ------------------------------------------------------------------------ */
/* Evaluator                                                                */
/* ------------------------------------------------------------------------ */

/* Entries of the operator stack. */
enum op {
    OP_LPAREN,
    OP_ADD,
    OP_SUB,
    OP_MUL,
    OP_DIV,
    OP_MOD,
    OP_NEG,
};

/* Binding strength of binary operators; OP_LPAREN acts as a barrier. */
static int precedence(enum op op)
{
    switch (op) {
    case OP_ADD:
    case OP_SUB:
        return 1;
    case OP_MUL:
    case OP_DIV:
    case OP_MOD:
        return 2;
    case OP_NEG:
        return 3;
    case OP_LPAREN:
        break;
    }
    return 0;
}

/* Scratch stacks, reused across lines and grown to the longest line seen. */
struct calc_stacks {
    int64_t *vals;
    unsigned char *ops;     /* enum op values */
    size_t cap;
};

static bool stacks_reserve(struct calc_stacks *st, size_t need)
{
    if (need <= st->cap)
        return true;

    size_t cap = st->cap ? st->cap : 64;
    while (cap < need)
        cap *= 2;

    int64_t *vals = realloc(st->vals, cap * sizeof *vals);
    if (vals == NULL)
        return false;
    st->vals = vals;

    unsigned char *ops = realloc(st->ops, cap * sizeof *ops);
    if (ops == NULL)
        return false;
    st->ops = ops;

    st->cap = cap;
    return true;
}

static void stacks_free(struct calc_stacks *st)
{
    free(st->vals);
    free(st->ops);
    *st = (struct calc_stacks){ 0 };
}

/* Pops the top operator and applies it to the value stack. */
static bool apply_top(struct calc_stacks *st, size_t *nvals, size_t *nops)
{
    enum op op = (enum op)st->ops[--*nops];

    if (op == OP_NEG)
        return checked_neg(st->vals[*nvals - 1], &st->vals[*nvals - 1]);

    int64_t b = st->vals[--*nvals];
    int64_t *a = &st->vals[*nvals - 1];

    switch (op) {
    case OP_ADD: return checked_add(*a, b, a);
    case OP_SUB: return checked_sub(*a, b, a);
    case OP_MUL: return checked_mul(*a, b, a);
    case OP_DIV: return checked_div(*a, b, a);
    case OP_MOD: return checked_mod(*a, b, a);
    case OP_NEG:
    case OP_LPAREN:
        break;
    }
    return false;
}

/* Applies operators on top of the stack that bind at least as tightly as
 * `prec` (all binary operators are left-associative), stopping at '('. */
static bool reduce(struct calc_stacks *st, size_t *nvals, size_t *nops, int prec)
{
    while (*nops > 0) {
        enum op top = (enum op)st->ops[*nops - 1];
        if (top == OP_LPAREN || precedence(top) < prec)
            break;
        if (!apply_top(st, nvals, nops))
            return false;
    }
    return true;
}

static bool is_blank(char c)
{
    return c == ' ' || c == '\t';
}

/*
 * Evaluates the expression in line[0..len). Returns CALC_OK and stores the
 * value in *out, or CALC_ERROR for any syntax or arithmetic error.
 */
static enum calc_status calc_eval(struct calc_stacks *st, const char *line,
                                  size_t len, int64_t *out)
{
    /* Every stack entry consumes at least one input byte. */
    if (!stacks_reserve(st, len + 1))
        return CALC_NOMEM;

    size_t nvals = 0, nops = 0;
    bool want_operand = true;
    size_t i = 0;

    while (i < len) {
        char c = line[i];

        if (is_blank(c)) {
            i++;
            continue;
        }

        if (want_operand) {
            if (c >= '0' && c <= '9') {
                int64_t v = 0;
                do {
                    int d = line[i] - '0';
                    if (v > (INT64_MAX - d) / 10)
                        return CALC_ERROR;
                    v = v * 10 + d;
                    i++;
                } while (i < len && line[i] >= '0' && line[i] <= '9');

                st->vals[nvals++] = v;
                if (!reduce(st, &nvals, &nops, precedence(OP_NEG)))
                    return CALC_ERROR;
                want_operand = false;
                continue;
            }
            if (c == '-')
                st->ops[nops++] = OP_NEG;
            else if (c == '(')
                st->ops[nops++] = OP_LPAREN;
            else
                return CALC_ERROR;
            i++;
            continue;
        }

        enum op op;
        switch (c) {
        case '+': op = OP_ADD; break;
        case '-': op = OP_SUB; break;
        case '*': op = OP_MUL; break;
        case '/': op = OP_DIV; break;
        case '%': op = OP_MOD; break;
        case ')':
            if (!reduce(st, &nvals, &nops, 0))
                return CALC_ERROR;
            if (nops == 0)
                return CALC_ERROR;          /* unmatched ')' */
            nops--;                         /* pop '(' */
            /* The parenthesised value completes a primary for pending '-'. */
            if (!reduce(st, &nvals, &nops, precedence(OP_NEG)))
                return CALC_ERROR;
            i++;
            continue;
        default:
            return CALC_ERROR;
        }

        if (!reduce(st, &nvals, &nops, precedence(op)))
            return CALC_ERROR;
        st->ops[nops++] = (unsigned char)op;
        want_operand = true;
        i++;
    }

    if (want_operand)
        return CALC_ERROR;                  /* empty input or missing operand */
    if (!reduce(st, &nvals, &nops, 0))
        return CALC_ERROR;
    if (nops != 0)
        return CALC_ERROR;                  /* unmatched '(' */

    *out = st->vals[0];
    return CALC_OK;
}

/* ------------------------------------------------------------------------ */
/* Line input                                                               */
/* ------------------------------------------------------------------------ */

struct line_reader {
    FILE *in;
    char *buf;
    size_t cap;
    size_t start;   /* first unconsumed byte */
    size_t end;     /* one past the last buffered byte */
    bool eof;
};

/*
 * Returns the next line (without its '\n') in *line / *len.
 * Returns 1 on success, 0 at end of input, -1 on allocation or read error.
 * The returned pointer is valid until the next call.
 */
static int next_line(struct line_reader *r, const char **line, size_t *len)
{
    size_t scanned = r->start;

    for (;;) {
        char *nl = (scanned < r->end)
                       ? memchr(r->buf + scanned, '\n', r->end - scanned)
                       : NULL;
        if (nl != NULL) {
            *line = r->buf + r->start;
            *len = (size_t)(nl - *line);
            r->start = (size_t)(nl - r->buf) + 1;
            return 1;
        }
        scanned = r->end;

        if (r->eof) {
            if (r->start == r->end)
                return 0;
            *line = r->buf + r->start;      /* final line without '\n' */
            *len = r->end - r->start;
            r->start = r->end;
            return 1;
        }

        /* Discard consumed bytes, then make room for more input. */
        if (r->start > 0) {
            memmove(r->buf, r->buf + r->start, r->end - r->start);
            r->end -= r->start;
            scanned -= r->start;
            r->start = 0;
        }
        if (r->end == r->cap) {
            size_t cap = r->cap ? r->cap * 2 : 1 << 16;
            char *buf = realloc(r->buf, cap);
            if (buf == NULL)
                return -1;
            r->buf = buf;
            r->cap = cap;
        }

        size_t n = fread(r->buf + r->end, 1, r->cap - r->end, r->in);
        r->end += n;
        if (n == 0) {
            if (ferror(r->in))
                return -1;
            r->eof = true;
        }
    }
}

static bool is_blank_line(const char *line, size_t len)
{
    for (size_t i = 0; i < len; i++) {
        if (!is_blank(line[i]))
            return false;
    }
    return true;
}

/* ------------------------------------------------------------------------ */
/* Entry point                                                              */
/* ------------------------------------------------------------------------ */

int calc_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    struct line_reader reader = { .in = stdin };
    struct calc_stacks stacks = { 0 };
    int status = EXIT_SUCCESS;
    const char *line;
    size_t len;
    int rc;

    while ((rc = next_line(&reader, &line, &len)) > 0) {
        if (is_blank_line(line, len))
            continue;

        int64_t value;
        enum calc_status res = calc_eval(&stacks, line, len, &value);
        if (res == CALC_NOMEM) {
            rc = -1;
            break;
        }
        if (res == CALC_OK)
            printf("%" PRId64 "\n", value);
        else
            fputs("error\n", stdout);
    }

    if (rc < 0) {
        fputs("calc: out of memory or read error\n", stderr);
        status = EXIT_FAILURE;
    }
    if (fflush(stdout) != 0) {
        perror("calc: write error");
        status = EXIT_FAILURE;
    }

    free(reader.buf);
    stacks_free(&stacks);
    return status;
}

/*
 * `app lru`: LRU cache simulator (see SPEC.md, section "lru").
 *
 * The whole of standard input is read into one buffer that stays alive (and
 * unmodified) until the end, so cache entries simply point at their key and
 * value bytes inside it: no per-entry string allocation is ever needed.
 *
 * Entries live in a growable pool and are addressed by 32-bit index. Each
 * entry sits on two intrusive lists:
 *   - a doubly linked recency list (head = most recent, tail = least recent);
 *   - a singly linked hash-bucket chain.
 * Every command is therefore O(1) expected time.
 */
#include "lru.h"

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NIL UINT32_MAX

/* ---------------------------------------------------------------- input */

struct slice {
    const char *ptr;
    size_t len;
};

static bool slice_eq(struct slice a, struct slice b)
{
    return a.len == b.len && memcmp(a.ptr, b.ptr, a.len) == 0;
}

static bool slice_is(struct slice s, const char *lit)
{
    size_t n = strlen(lit);
    return s.len == n && memcmp(s.ptr, lit, n) == 0;
}

/* Reads all of `in` into a heap buffer. Returns NULL on allocation/IO error. */
static char *read_all(FILE *in, size_t *out_len)
{
    size_t cap = 1 << 20, len = 0;
    char *buf = malloc(cap);
    if (buf == NULL)
        return NULL;

    for (;;) {
        if (len == cap) {
            size_t ncap = cap * 2;
            char *nbuf = realloc(buf, ncap);
            if (nbuf == NULL) {
                free(buf);
                return NULL;
            }
            buf = nbuf;
            cap = ncap;
        }
        size_t n = fread(buf + len, 1, cap - len, in);
        len += n;
        if (n == 0) {
            if (ferror(in)) {
                free(buf);
                return NULL;
            }
            break;
        }
    }
    *out_len = len;
    return buf;
}

/* Splits the next line off [*cur, end); strips a trailing '\r'. */
static bool next_line(const char **cur, const char *end, struct slice *line)
{
    const char *p = *cur;
    if (p >= end)
        return false;

    const char *nl = memchr(p, '\n', (size_t)(end - p));
    const char *stop = nl != NULL ? nl : end;
    *cur = nl != NULL ? nl + 1 : end;

    if (stop > p && stop[-1] == '\r')
        stop--;
    line->ptr = p;
    line->len = (size_t)(stop - p);
    return true;
}

/* Splits up to `max` space-separated tokens from `line`; returns the count,
 * or max + 1 if there are more tokens than that. */
static size_t tokenize(struct slice line, struct slice *tok, size_t max)
{
    const char *p = line.ptr, *end = line.ptr + line.len;
    size_t n = 0;

    for (;;) {
        while (p < end && *p == ' ')
            p++;
        if (p == end)
            return n;
        if (n == max)
            return max + 1;
        const char *start = p;
        while (p < end && *p != ' ')
            p++;
        tok[n].ptr = start;
        tok[n].len = (size_t)(p - start);
        n++;
    }
}

/* Parses a decimal capacity in [1, 1000000] surrounded by optional blanks. */
static bool parse_capacity(struct slice s, uint32_t *out)
{
    const char *p = s.ptr, *end = s.ptr + s.len;
    while (p < end && (*p == ' ' || *p == '\t'))
        p++;
    while (end > p && (end[-1] == ' ' || end[-1] == '\t'))
        end--;
    if (p < end && *p == '+')
        p++;
    if (p == end)
        return false;

    uint64_t v = 0;
    for (; p < end; p++) {
        if (*p < '0' || *p > '9')
            return false;
        v = v * 10 + (uint64_t)(*p - '0');
        if (v > 1000000)
            return false;
    }
    if (v == 0)
        return false;
    *out = (uint32_t)v;
    return true;
}

/* --------------------------------------------------------------- output */

struct outbuf {
    char *buf;
    size_t len, cap;
    FILE *out;
};

static void out_flush(struct outbuf *o)
{
    if (o->len > 0) {
        fwrite(o->buf, 1, o->len, o->out);
        o->len = 0;
    }
}

static void out_write(struct outbuf *o, const char *s, size_t n)
{
    if (o->cap - o->len < n + 1) {
        out_flush(o);
        if (o->cap < n + 1) {
            fwrite(s, 1, n, o->out);
            fputc('\n', o->out);
            return;
        }
    }
    memcpy(o->buf + o->len, s, n);
    o->len += n;
    o->buf[o->len++] = '\n';
}

static void out_uint(struct outbuf *o, uint32_t v)
{
    char tmp[16];
    size_t i = sizeof tmp;
    do {
        tmp[--i] = (char)('0' + v % 10);
        v /= 10;
    } while (v != 0);
    out_write(o, tmp + i, sizeof tmp - i);
}

/* ---------------------------------------------------------------- cache */

struct entry {
    struct slice key;
    struct slice value;
    uint32_t hash;
    uint32_t prev, next;  /* recency list; prev is toward the head (MRU) */
    uint32_t chain;       /* next entry in the same hash bucket, or free list */
};

struct cache {
    struct entry *pool;
    uint32_t pool_len, pool_cap;
    uint32_t free_head;

    uint32_t *buckets;
    uint32_t mask;         /* bucket count - 1; bucket count is a power of 2 */

    uint32_t head, tail;
    uint32_t size, capacity;
};

static uint32_t hash_bytes(struct slice s)
{
    /* FNV-1a, then a murmur3 finalizer to spread the low bits. */
    uint64_t h = 0xcbf29ce484222325u;
    for (size_t i = 0; i < s.len; i++) {
        h ^= (unsigned char)s.ptr[i];
        h *= 0x100000001b3u;
    }
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdu;
    h ^= h >> 33;
    h *= 0xc4ceb9fe1a85ec53u;
    h ^= h >> 33;
    return (uint32_t)h;
}

static bool cache_init(struct cache *c, uint32_t capacity)
{
    *c = (struct cache){
        .free_head = NIL, .head = NIL, .tail = NIL, .capacity = capacity,
    };
    uint32_t nbuckets = 1024;
    c->buckets = malloc(nbuckets * sizeof *c->buckets);
    if (c->buckets == NULL)
        return false;
    memset(c->buckets, 0xff, nbuckets * sizeof *c->buckets);
    c->mask = nbuckets - 1;
    return true;
}

static void cache_free(struct cache *c)
{
    free(c->pool);
    free(c->buckets);
}

/* Doubles the bucket array and redistributes the live entries. */
static bool cache_rehash(struct cache *c)
{
    uint32_t nbuckets = (c->mask + 1) * 2;
    uint32_t *nb = malloc((size_t)nbuckets * sizeof *nb);
    if (nb == NULL)
        return false;
    memset(nb, 0xff, (size_t)nbuckets * sizeof *nb);

    uint32_t nmask = nbuckets - 1;
    for (uint32_t i = c->head; i != NIL; i = c->pool[i].next) {
        uint32_t b = c->pool[i].hash & nmask;
        c->pool[i].chain = nb[b];
        nb[b] = i;
    }
    free(c->buckets);
    c->buckets = nb;
    c->mask = nmask;
    return true;
}

/* Returns the index of a free pool slot, growing the pool if needed. */
static uint32_t cache_alloc(struct cache *c)
{
    if (c->free_head != NIL) {
        uint32_t i = c->free_head;
        c->free_head = c->pool[i].chain;
        return i;
    }
    if (c->pool_len == c->pool_cap) {
        uint32_t ncap = c->pool_cap ? c->pool_cap * 2 : 1024;
        if (ncap > c->capacity)
            ncap = c->capacity;
        struct entry *np = realloc(c->pool, (size_t)ncap * sizeof *np);
        if (np == NULL)
            return NIL;
        c->pool = np;
        c->pool_cap = ncap;
    }
    return c->pool_len++;
}

/* Finds `key`; on return *link points at the chain slot that references it
 * (or at the terminating NIL of its bucket if absent). */
static uint32_t cache_find(struct cache *c, struct slice key, uint32_t hash,
                           uint32_t **link)
{
    uint32_t *l = &c->buckets[hash & c->mask];
    while (*l != NIL) {
        struct entry *e = &c->pool[*l];
        if (e->hash == hash && slice_eq(e->key, key))
            break;
        l = &e->chain;
    }
    *link = l;
    return *l;
}

static void list_unlink(struct cache *c, uint32_t i)
{
    struct entry *e = &c->pool[i];
    if (e->prev != NIL)
        c->pool[e->prev].next = e->next;
    else
        c->head = e->next;
    if (e->next != NIL)
        c->pool[e->next].prev = e->prev;
    else
        c->tail = e->prev;
}

static void list_push_front(struct cache *c, uint32_t i)
{
    struct entry *e = &c->pool[i];
    e->prev = NIL;
    e->next = c->head;
    if (c->head != NIL)
        c->pool[c->head].prev = i;
    else
        c->tail = i;
    c->head = i;
}

static void cache_touch(struct cache *c, uint32_t i)
{
    if (c->head != i) {
        list_unlink(c, i);
        list_push_front(c, i);
    }
}

/* Unlinks entry i, whose chain slot is *link, and returns it to the pool. */
static void cache_remove_at(struct cache *c, uint32_t *link, uint32_t i)
{
    *link = c->pool[i].chain;
    list_unlink(c, i);
    c->pool[i].chain = c->free_head;
    c->free_head = i;
    c->size--;
}

static void cache_remove(struct cache *c, uint32_t i)
{
    uint32_t *link;
    cache_find(c, c->pool[i].key, c->pool[i].hash, &link);
    cache_remove_at(c, link, i);
}

static bool cache_set(struct cache *c, struct slice key, struct slice value)
{
    uint32_t hash = hash_bytes(key);
    uint32_t *link;
    uint32_t i = cache_find(c, key, hash, &link);

    if (i != NIL) {
        c->pool[i].value = value;
        cache_touch(c, i);
        return true;
    }

    /* Inserting then evicting the LRU is equivalent to evicting first. */
    if (c->size == c->capacity)
        cache_remove(c, c->tail);

    if (c->size >= c->mask + 1 && !cache_rehash(c))
        return false;

    i = cache_alloc(c);
    if (i == NIL)
        return false;

    struct entry *e = &c->pool[i];
    e->key = key;
    e->value = value;
    e->hash = hash;
    uint32_t b = hash & c->mask;
    e->chain = c->buckets[b];
    c->buckets[b] = i;
    list_push_front(c, i);
    c->size++;
    return true;
}

static const struct slice *cache_get(struct cache *c, struct slice key)
{
    uint32_t *link;
    uint32_t i = cache_find(c, key, hash_bytes(key), &link);
    if (i == NIL)
        return NULL;
    cache_touch(c, i);
    return &c->pool[i].value;
}

static bool cache_del(struct cache *c, struct slice key)
{
    uint32_t *link;
    uint32_t i = cache_find(c, key, hash_bytes(key), &link);
    if (i == NIL)
        return false;
    cache_remove_at(c, link, i);
    return true;
}

/* ----------------------------------------------------------------- main */

/* Executes every command line; returns false on allocation failure. */
static bool run(const char *cur, const char *end, struct cache *c,
                struct outbuf *o)
{
    struct slice line, tok[3];

    while (next_line(&cur, end, &line)) {
        size_t n = tokenize(line, tok, 3);
        if (n == 0 || n > 3)
            continue;

        if (n == 3 && slice_is(tok[0], "SET")) {
            if (!cache_set(c, tok[1], tok[2]))
                return false;
        } else if (n == 2 && slice_is(tok[0], "GET")) {
            const struct slice *v = cache_get(c, tok[1]);
            if (v != NULL)
                out_write(o, v->ptr, v->len);
            else
                out_write(o, "NULL", 4);
        } else if (n == 2 && slice_is(tok[0], "DEL")) {
            out_write(o, cache_del(c, tok[1]) ? "1" : "0", 1);
        } else if (n == 1 && slice_is(tok[0], "SIZE")) {
            out_uint(o, c->size);
        }
        /* Anything else is not a valid command and is ignored. */
    }
    return true;
}

int lru_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    size_t len;
    char *input = read_all(stdin, &len);
    if (input == NULL) {
        fputs("lru: failed to read standard input\n", stderr);
        return EXIT_FAILURE;
    }

    const char *cur = input, *end = input + len;
    struct slice first;
    uint32_t capacity;
    if (!next_line(&cur, end, &first) || !parse_capacity(first, &capacity)) {
        free(input);
        fputs("lru: invalid capacity\n", stderr);
        return EXIT_FAILURE;
    }

    struct cache cache;
    static char obuf[1 << 16];
    struct outbuf out = { .buf = obuf, .cap = sizeof obuf, .out = stdout };
    int status = EXIT_SUCCESS;

    if (!cache_init(&cache, capacity) || !run(cur, end, &cache, &out)) {
        fputs("lru: out of memory\n", stderr);
        status = EXIT_FAILURE;
    }
    out_flush(&out);
    if (fflush(stdout) != 0 || ferror(stdout)) {
        fputs("lru: write error\n", stderr);
        status = EXIT_FAILURE;
    }

    cache_free(&cache);
    free(input);
    return status;
}

/*
 * suite: command-line entry point.
 *
 * Dispatches the first argument to the matching subcommand. Each subcommand
 * lives in its own module under src/<name>/ and exposes a single entry point
 * with the same signature as main(); it receives argv shifted so that
 * argv[0] is the subcommand name.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "calc/calc.h"
#include "lru/lru.h"
#include "wordfreq/wordfreq.h"

typedef int (*command_fn)(int argc, char **argv);

struct command {
    const char *name;
    command_fn run;
};

static const struct command commands[] = {
    { "wordfreq", wordfreq_main },
    { "lru",      lru_main },
    { "calc",     calc_main },
};

enum { NUM_COMMANDS = sizeof commands / sizeof commands[0] };

static void usage(FILE *out, const char *prog)
{
    fprintf(out, "usage: %s <command>\n\ncommands:\n", prog);
    for (size_t i = 0; i < NUM_COMMANDS; i++)
        fprintf(out, "  %s\n", commands[i].name);
}

int main(int argc, char **argv)
{
    const char *prog = (argc > 0 && argv[0] != NULL) ? argv[0] : "app";

    if (argc < 2) {
        usage(stderr, prog);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < NUM_COMMANDS; i++) {
        if (strcmp(argv[1], commands[i].name) == 0)
            return commands[i].run(argc - 1, argv + 1);
    }

    fprintf(stderr, "%s: unknown command '%s'\n", prog, argv[1]);
    usage(stderr, prog);
    return EXIT_FAILURE;
}

/*
 * `app wordfreq`: print the 10 most frequent words of standard input.
 *
 * A word is a maximal run of ASCII letters, folded to lowercase; every other
 * byte separates words. Input is streamed in fixed-size chunks, so memory use
 * is proportional to the distinct words rather than the input size. Words are
 * counted in an open-addressing hash table whose keys live in a single
 * growable byte pool; the top entries are then selected in one pass.
 */
#include "wordfreq.h"

#include <inttypes.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum {
    TOP_N         = 10,
    READ_CHUNK    = 1 << 16,
    INITIAL_SLOTS = 1 << 12, /* must be a power of two */
};

/* FNV-1a, 64-bit. */
#define FNV_OFFSET UINT64_C(0xcbf29ce484222325)
#define FNV_PRIME  UINT64_C(0x100000001b3)

/* A growable byte buffer. */
struct buf {
    char  *data;
    size_t len;
    size_t cap;
};

/*
 * One distinct word; count == 0 marks an empty slot. Fields are 32-bit to
 * keep the slot array compact: a 50 MB input holds far fewer than 2^32
 * words, and table_add() refuses to go past those limits.
 */
struct entry {
    uint32_t hash;  /* low 32 bits of the word's hash */
    uint32_t count;
    uint32_t off;   /* offset of the word in the pool */
    uint32_t len;
};

struct table {
    struct entry *slots;
    size_t        mask; /* number of slots - 1 */
    size_t        used;
    struct buf    pool; /* concatenated word bytes, not NUL-terminated */
};

/* Maps each byte to its lowercase letter, or 0 if it is not a letter. */
static unsigned char fold[256];

static void init_fold(void)
{
    for (int c = 'a'; c <= 'z'; c++) {
        fold[c] = (unsigned char)c;
        fold[c - 'a' + 'A'] = (unsigned char)c;
    }
}

static bool buf_reserve(struct buf *b, size_t extra)
{
    if (b->cap - b->len >= extra)
        return true;
    if (extra > SIZE_MAX - b->len)
        return false;
    size_t need = b->len + extra;
    size_t cap = b->cap ? b->cap : 64;
    while (cap < need)
        cap = cap > SIZE_MAX / 2 ? need : cap * 2;
    char *p = realloc(b->data, cap);
    if (p == NULL)
        return false;
    b->data = p;
    b->cap = cap;
    return true;
}

static bool buf_append(struct buf *b, const char *src, size_t n)
{
    if (!buf_reserve(b, n))
        return false;
    memcpy(b->data + b->len, src, n);
    b->len += n;
    return true;
}

static bool table_init(struct table *t)
{
    t->slots = calloc(INITIAL_SLOTS, sizeof *t->slots);
    if (t->slots == NULL)
        return false;
    t->mask = INITIAL_SLOTS - 1;
    t->used = 0;
    t->pool = (struct buf){ 0 };
    return true;
}

static void table_free(struct table *t)
{
    free(t->slots);
    free(t->pool.data);
}

/* Doubles the slot array and reinserts every entry. */
static bool table_grow(struct table *t)
{
    size_t nslots = (t->mask + 1) * 2;
    struct entry *slots = calloc(nslots, sizeof *slots);
    if (slots == NULL)
        return false;
    size_t mask = nslots - 1;
    for (size_t i = 0; i <= t->mask; i++) {
        const struct entry *e = &t->slots[i];
        if (e->count == 0)
            continue;
        size_t j = e->hash & mask;
        while (slots[j].count != 0)
            j = (j + 1) & mask;
        slots[j] = *e;
    }
    free(t->slots);
    t->slots = slots;
    t->mask = mask;
    return true;
}

/* Counts one occurrence of the lowercase word w[0..len). */
static bool table_add(struct table *t, const char *w, size_t len, uint64_t hash64)
{
    uint32_t hash = (uint32_t)(hash64 ^ (hash64 >> 32));
    size_t i = hash & t->mask;
    for (;;) {
        struct entry *e = &t->slots[i];
        if (e->count == 0)
            break;
        if (e->hash == hash && e->len == len &&
            memcmp(t->pool.data + e->off, w, len) == 0) {
            if (e->count == UINT32_MAX)
                return false;
            e->count++;
            return true;
        }
        i = (i + 1) & t->mask;
    }

    size_t off = t->pool.len;
    if (len > UINT32_MAX - off || !buf_append(&t->pool, w, len))
        return false;
    t->slots[i] = (struct entry){
        .hash = hash, .count = 1, .off = (uint32_t)off, .len = (uint32_t)len,
    };
    t->used++;

    /* Keep the load factor at or below 3/4. */
    if (t->used > (t->mask + 1) / 4 * 3)
        return table_grow(t);
    return true;
}

/* Reads standard input to the end, counting every word into t. */
static bool count_words(FILE *in, struct table *t)
{
    static char chunk[READ_CHUNK];
    struct buf word = { 0 }; /* current word, possibly spanning chunks */
    uint64_t hash = FNV_OFFSET;
    bool ok = true;
    size_t n;

    while (ok && (n = fread(chunk, 1, sizeof chunk, in)) > 0) {
        for (size_t i = 0; i < n; i++) {
            unsigned char c = fold[(unsigned char)chunk[i]];
            if (c != 0) {
                if (word.len == word.cap && !buf_reserve(&word, 1)) {
                    ok = false;
                    break;
                }
                word.data[word.len++] = (char)c;
                hash = (hash ^ c) * FNV_PRIME;
            } else if (word.len > 0) {
                if (!table_add(t, word.data, word.len, hash)) {
                    ok = false;
                    break;
                }
                word.len = 0;
                hash = FNV_OFFSET;
            }
        }
    }
    if (ok && word.len > 0)
        ok = table_add(t, word.data, word.len, hash);
    free(word.data);

    if (!ok) {
        fputs("wordfreq: out of memory or input too large\n", stderr);
        return false;
    }
    if (ferror(in)) {
        perror("wordfreq: read error");
        return false;
    }
    return true;
}

/* Byte-wise comparison of two words; a proper prefix sorts first. */
static int word_cmp(const struct table *t, const struct entry *a, const struct entry *b)
{
    size_t n = a->len < b->len ? a->len : b->len;
    int r = memcmp(t->pool.data + a->off, t->pool.data + b->off, n);
    if (r != 0)
        return r;
    return (a->len > b->len) - (a->len < b->len);
}

/* True if a ranks before b: higher count first, then word ascending. */
static bool ranks_before(const struct table *t, const struct entry *a, const struct entry *b)
{
    if (a->count != b->count)
        return a->count > b->count;
    return word_cmp(t, a, b) < 0;
}

/*
 * Fills top[] with the best-ranked entries in rank order and returns how
 * many there are (at most TOP_N).
 */
static size_t select_top(const struct table *t, const struct entry *top[TOP_N])
{
    size_t k = 0;
    for (size_t i = 0; i <= t->mask; i++) {
        const struct entry *e = &t->slots[i];
        if (e->count == 0)
            continue;
        if (k == TOP_N && !ranks_before(t, e, top[k - 1]))
            continue;
        size_t j = k < TOP_N ? k++ : k - 1;
        while (j > 0 && ranks_before(t, e, top[j - 1])) {
            top[j] = top[j - 1];
            j--;
        }
        top[j] = e;
    }
    return k;
}

int wordfreq_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    init_fold();

    struct table t;
    if (!table_init(&t)) {
        fputs("wordfreq: out of memory\n", stderr);
        return EXIT_FAILURE;
    }
    if (!count_words(stdin, &t)) {
        table_free(&t);
        return EXIT_FAILURE;
    }

    const struct entry *top[TOP_N];
    size_t k = select_top(&t, top);
    for (size_t i = 0; i < k; i++) {
        const struct entry *e = top[i];
        printf("%" PRIu32 " ", e->count);
        fwrite(t.pool.data + e->off, 1, e->len, stdout);
        putchar('\n');
    }
    table_free(&t);

    if (fflush(stdout) != 0 || ferror(stdout)) {
        perror("wordfreq: write error");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
